(function() {
  window.CardSpoke.Plugin.register('word-counter', {
    manifest: {
      name: 'Word Counter',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Displays word count for each card in the card footer',
      layer: 'feature',
      permissions: []
    },
    setup: async function(ctx) {
      ctx.logger.info('Word Counter loaded');
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'word-counter-render',
          priority: 10,
          operations: ['card.render'],
          handler: async function(mwCtx, next) {
            await next();
            var card = mwCtx.args[0];
            var element = mwCtx.args[1];
            if (!card || !element) return;
            var existing = element.querySelector('.mod-word-count');
            if (existing) existing.remove();
            var text = (card.title || '') + ' ' + (card.body || '');
            var words = text.trim().split(/\s+/).filter(function(w) { return w.length > 0; });
            var count = words.length;
            var readingTime = Math.ceil(count / 200);
            var el = document.createElement('div');
            el.className = 'mod-word-count';
            el.textContent = count + ' words' + (readingTime > 0 ? ' (~' + readingTime + ' min)' : '');
            element.appendChild(el);
          }
        });
      }
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('word-counter-render');
      }
      var counters = document.querySelectorAll('.mod-word-count');
      counters.forEach(function(c) { c.remove(); });
      ctx.logger.info('Word Counter disabled');
    }
  });
})();
